-- ============================================================================
-- STEM IDEA GENERATOR - MASTER SUPABASE DATABASE SCHEMA
-- ============================================================================
-- This schema includes all tables needed for the complete application:
-- 1. Users (guest users with random IDs)
-- 2. Components (100 electronics components)
-- 3. Projects (AI-generated project ideas)
-- 4. Chat Messages (AI guidance conversations)
-- 5. Project Progress (step tracking and progress)
-- ============================================================================

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================================================
-- TABLE: users
-- Stores guest users with randomly generated IDs (no authentication required)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.users (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    guest_id VARCHAR(255) UNIQUE NOT NULL,  -- Random guest ID stored in browser
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    last_active TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    preferences JSONB DEFAULT '{}',  -- User preferences like theme, etc.
    metadata JSONB DEFAULT '{}'  -- Any additional user data
);

-- ============================================================================
-- TABLE: components
-- Electronics components with detailed specifications
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.components (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL,
    description TEXT,
    price DECIMAL(10,2),
    currency VARCHAR(3) DEFAULT 'USD',
    in_stock BOOLEAN DEFAULT true,
    stock_count INTEGER DEFAULT 0,
    manufacturer VARCHAR(255),
    model_number VARCHAR(100),
    datasheet_url TEXT,
    image_url TEXT,
    specifications JSONB DEFAULT '{}',
    tags TEXT[] DEFAULT '{}',
    dimensions JSONB DEFAULT '{}',  -- {width, height, depth, unit}
    weight DECIMAL(8,3),  -- in grams
    operating_voltage_min DECIMAL(5,2),
    operating_voltage_max DECIMAL(5,2),
    operating_current DECIMAL(8,3),  -- in mA
    power_consumption DECIMAL(8,3),  -- in watts
    interface_type VARCHAR(100),  -- I2C, SPI, UART, Digital, Analog, etc.
    pin_count INTEGER,
    package_type VARCHAR(50),  -- DIP, SMD, Module, etc.
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- TABLE: projects
-- User's saved project ideas (generated by AI)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.projects (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    title VARCHAR(500) NOT NULL,
    description TEXT,
    difficulty VARCHAR(50),  -- Beginner, Intermediate, Advanced, Expert
    estimated_time VARCHAR(100),
    estimated_cost VARCHAR(100),
    components TEXT[] DEFAULT '{}',  -- List of component names
    skills TEXT[] DEFAULT '{}',  -- Required skills
    steps TEXT[] DEFAULT '{}',  -- Project steps
    status VARCHAR(50) DEFAULT 'planning',  -- planning, in-progress, completed, abandoned
    progress INTEGER DEFAULT 0 CHECK (progress >= 0 AND progress <= 100),
    notes TEXT DEFAULT '',
    starred BOOLEAN DEFAULT false,
    tags TEXT[] DEFAULT '{}',
    completed_steps INTEGER[] DEFAULT '{}',  -- Array of completed step indices
    generated_from_params JSONB DEFAULT '{}',  -- Original generation parameters
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- TABLE: chat_messages
-- AI guidance chat messages for each project
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.chat_messages (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    project_id UUID REFERENCES public.projects(id) ON DELETE CASCADE,
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    session_id VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL,  -- 'user' or 'assistant'
    content TEXT NOT NULL,
    message_type VARCHAR(50) DEFAULT 'text',  -- text, guidance, blocker_help, clarification
    metadata JSONB DEFAULT '{}',  -- Additional message metadata
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- TABLE: component_reviews (Optional - for future enhancement)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.component_reviews (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    component_id UUID REFERENCES public.components(id) ON DELETE CASCADE,
    user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
    user_name VARCHAR(255),
    rating INTEGER CHECK (rating >= 1 AND rating <= 5),
    review_text TEXT,
    pros TEXT[],
    cons TEXT[],
    use_case TEXT,
    difficulty_level VARCHAR(20) CHECK (difficulty_level IN ('Beginner', 'Intermediate', 'Advanced', 'Expert')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- TABLE: component_projects (Optional - linking components to project examples)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.component_projects (
    id UUID DEFAULT uuid_generate_v4() PRIMARY KEY,
    component_id UUID REFERENCES public.components(id) ON DELETE CASCADE,
    project_name VARCHAR(255) NOT NULL,
    project_description TEXT,
    project_url TEXT,
    difficulty_level VARCHAR(20) CHECK (difficulty_level IN ('Beginner', 'Intermediate', 'Advanced', 'Expert')),
    estimated_time VARCHAR(50),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ============================================================================
-- INDEXES for performance optimization
-- ============================================================================
CREATE INDEX IF NOT EXISTS idx_users_guest_id ON public.users(guest_id);
CREATE INDEX IF NOT EXISTS idx_users_last_active ON public.users(last_active);

CREATE INDEX IF NOT EXISTS idx_components_category ON public.components(category);
CREATE INDEX IF NOT EXISTS idx_components_name ON public.components(name);
CREATE INDEX IF NOT EXISTS idx_components_in_stock ON public.components(in_stock);
CREATE INDEX IF NOT EXISTS idx_components_price ON public.components(price);

CREATE INDEX IF NOT EXISTS idx_projects_user_id ON public.projects(user_id);
CREATE INDEX IF NOT EXISTS idx_projects_status ON public.projects(status);
CREATE INDEX IF NOT EXISTS idx_projects_starred ON public.projects(starred);
CREATE INDEX IF NOT EXISTS idx_projects_created_at ON public.projects(created_at DESC);

CREATE INDEX IF NOT EXISTS idx_chat_messages_project_id ON public.chat_messages(project_id);
CREATE INDEX IF NOT EXISTS idx_chat_messages_user_id ON public.chat_messages(user_id);
CREATE INDEX IF NOT EXISTS idx_chat_messages_session_id ON public.chat_messages(session_id);
CREATE INDEX IF NOT EXISTS idx_chat_messages_created_at ON public.chat_messages(created_at DESC);

CREATE INDEX IF NOT EXISTS idx_component_reviews_component_id ON public.component_reviews(component_id);
CREATE INDEX IF NOT EXISTS idx_component_reviews_rating ON public.component_reviews(rating);

-- ============================================================================
-- TRIGGERS for automatic timestamp updates
-- ============================================================================
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_components_updated_at 
    BEFORE UPDATE ON public.components 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_projects_updated_at 
    BEFORE UPDATE ON public.projects 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

-- ============================================================================
-- ROW LEVEL SECURITY (RLS) Policies
-- Since we're using guest users without auth, we'll make data public
-- but you can customize this later if you add authentication
-- ============================================================================
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.components ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.component_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.component_projects ENABLE ROW LEVEL SECURITY;

-- Allow all operations for now (guest users)
CREATE POLICY "Allow all operations on users" ON public.users FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all operations on components" ON public.components FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all operations on projects" ON public.projects FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all operations on chat_messages" ON public.chat_messages FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all operations on component_reviews" ON public.component_reviews FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow all operations on component_projects" ON public.component_projects FOR ALL USING (true) WITH CHECK (true);

