-- ============================================================================
-- UTILITY FUNCTIONS
-- ============================================================================

-- Function to get component details with related data
CREATE OR REPLACE FUNCTION get_component_details(component_uuid UUID)
RETURNS JSON AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'component', row_to_json(c),
        'reviews', COALESCE(reviews.reviews, '[]'::json),
        'projects', COALESCE(projects.projects, '[]'::json),
        'stats', json_build_object(
            'average_rating', COALESCE(AVG(r.rating), 0),
            'review_count', COUNT(DISTINCT r.id),
            'project_count', COUNT(DISTINCT p.id)
        )
    ) INTO result
    FROM public.components c
    LEFT JOIN public.component_reviews r ON c.id = r.component_id
    LEFT JOIN public.component_projects p ON c.id = p.component_id
    LEFT JOIN LATERAL (
        SELECT json_agg(row_to_json(rev)) as reviews
        FROM public.component_reviews rev
        WHERE rev.component_id = c.id
    ) reviews ON true
    LEFT JOIN LATERAL (
        SELECT json_agg(row_to_json(proj)) as projects
        FROM public.component_projects proj
        WHERE proj.component_id = c.id
    ) projects ON true
    WHERE c.id = component_uuid
    GROUP BY c.id, reviews.reviews, projects.projects;
    
    RETURN result;
END;
$$ LANGUAGE plpgsql;

-- Function to get user's projects with stats
CREATE OR REPLACE FUNCTION get_user_projects(user_guest_id VARCHAR)
RETURNS JSON AS $$
DECLARE
    result JSON;
    user_uuid UUID;
BEGIN
    -- Get user UUID from guest_id
    SELECT id INTO user_uuid FROM public.users WHERE guest_id = user_guest_id;
    
    IF user_uuid IS NULL THEN
        RETURN '[]'::json;
    END IF;
    
    SELECT json_agg(
        json_build_object(
            'project', row_to_json(p),
            'chat_count', (
                SELECT COUNT(*) FROM public.chat_messages 
                WHERE project_id = p.id
            )
        ) ORDER BY p.created_at DESC
    ) INTO result
    FROM public.projects p
    WHERE p.user_id = user_uuid;
    
    RETURN COALESCE(result, '[]'::json);
END;
$$ LANGUAGE plpgsql;

-- Function to get project chat history
CREATE OR REPLACE FUNCTION get_project_chat_history(
    project_uuid UUID,
    message_limit INTEGER DEFAULT 100
)
RETURNS JSON AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_agg(
        row_to_json(cm) ORDER BY cm.created_at ASC
    ) INTO result
    FROM (
        SELECT * FROM public.chat_messages
        WHERE project_id = project_uuid
        ORDER BY created_at DESC
        LIMIT message_limit
    ) cm;
    
    RETURN COALESCE(result, '[]'::json);
END;
$$ LANGUAGE plpgsql;

